-- Additive only: uploaded statements, journals and old plan records are untouched.
CREATE TABLE IF NOT EXISTS parties (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,uuid CHAR(36) NOT NULL UNIQUE,household_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,kind VARCHAR(20) NOT NULL DEFAULT 'person',active TINYINT NOT NULL DEFAULT 1,row_version INT NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NULL,UNIQUE(household_id,id),UNIQUE(household_id,name),FOREIGN KEY(household_id) REFERENCES households(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS party_accounts (household_id BIGINT UNSIGNED NOT NULL,party_id BIGINT UNSIGNED NOT NULL,ledger_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(household_id,ledger_id),FOREIGN KEY(household_id,party_id) REFERENCES parties(household_id,id),FOREIGN KEY(household_id,ledger_id) REFERENCES ledger_accounts(household_id,id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS party_entries (household_id BIGINT UNSIGNED NOT NULL,transaction_id BIGINT UNSIGNED NOT NULL,party_id BIGINT UNSIGNED NOT NULL,action VARCHAR(40) NOT NULL,payload_json JSON NOT NULL,PRIMARY KEY(household_id,transaction_id),FOREIGN KEY(household_id,transaction_id) REFERENCES transactions(household_id,id),FOREIGN KEY(household_id,party_id) REFERENCES parties(household_id,id)) ENGINE=InnoDB;
